import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.orders().listOrders(
        Map.of("order_status", "in_progress", "payment_status", "unpaid", "limit", 10));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("orders")) {
    Map<?, ?> order = (Map<?, ?>) row;
    Map<?, ?> totals = (Map<?, ?>) order.get("charges_totals");
    System.out.println(order.get("order_id") + " " + order.get("internal_id") + " "
            + order.get("order_status") + " " + totals.get("grand_total"));
}
Map<?, ?> pagination = (Map<?, ?>) body.get("pagination");
System.out.println(pagination.get("total") + " " + pagination.get("has_next"));

